**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int tab[6][6];
    for (int i = 0; i < 6; i++)
        for (int j = 0; j < 6; j++)
            plik >> tab[i][j];

    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};
    int cnt = 0;

    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            if (tab[i][j] == 0) {
                bool maSasiada = false;
                for (int d = 0; d < 4; d++) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (ni >= 0 && ni < 6 && nj >= 0 && nj < 6 && tab[ni][nj] == 1)
                        maSasiada = true;
                }
                if (maSasiada) cnt++;
            }
        }
    }

    cout << "Zera z sasiadem 1: " << cnt << endl;
    return 0;
}
```

**Wyjasnienie**: Dla kazdego zera sprawdzamy czy ma przynajmniej jednego sasiada-jedynke w sasiedztwie 4-spojnym.

